-- Admin-managed plus/minus fields on the OMI/listino base.
-- Seeded from engine/model.mjs (Excel CALCOLI maps). Piano/anno keep only rialzato/1900 scores.

create table if not exists stimaimmobile.valuation_fields (
  id text primary key check (id ~ '^[a-z][A-Za-z0-9]{0,63}$'),
  label text not null check (char_length(label) between 1 and 180),
  group_name text not null check (char_length(group_name) between 1 and 80),
  control_type text not null check (control_type in ('select', 'yesno', 'count', 'number')),
  sort_order integer not null,
  required boolean not null default false,
  active boolean not null default true,
  partial boolean not null default false,
  min_value numeric,
  max_value numeric,
  step_value numeric,
  fallback numeric,
  when_field_id text,
  when_values text[] not null default '{}',
  updated_at timestamptz not null default now()
);
create index if not exists valuation_fields_sort on stimaimmobile.valuation_fields(sort_order);

create table if not exists stimaimmobile.valuation_options (
  id uuid primary key default gen_random_uuid(),
  field_id text not null references stimaimmobile.valuation_fields(id) on delete cascade,
  value text not null check (char_length(value) between 1 and 180),
  label text not null check (char_length(label) between 1 and 180),
  coefficient numeric(8,2) not null,
  scored boolean not null default true,
  public boolean not null default true,
  sort_order integer not null,
  aliases text[] not null default '{}',
  unique (field_id, value)
);
create index if not exists valuation_options_field on stimaimmobile.valuation_options(field_id, sort_order);

do $$ begin
  alter table stimaimmobile.valuation_fields
    add constraint valuation_fields_when_fk
    foreign key (when_field_id) references stimaimmobile.valuation_fields(id) on delete set null deferrable initially deferred;
exception when duplicate_object then null;
end $$;

alter table stimaimmobile.valuation_fields enable row level security;
alter table stimaimmobile.valuation_options enable row level security;
revoke all on stimaimmobile.valuation_fields, stimaimmobile.valuation_options from public, anon, authenticated;
grant select, insert, update, delete on stimaimmobile.valuation_fields, stimaimmobile.valuation_options to stimaimmobile_app;
drop policy if exists app_access_valuation_fields on stimaimmobile.valuation_fields;
drop policy if exists app_access_valuation_options on stimaimmobile.valuation_options;
create policy app_access_valuation_fields on stimaimmobile.valuation_fields for all to stimaimmobile_app using (true) with check (true);
create policy app_access_valuation_options on stimaimmobile.valuation_options for all to stimaimmobile_app using (true) with check (true);

-- Starting €/m² is the published listino (OMI midpoint from publish_omi_rates, plus
-- the Brescia Excel demo). Min/max come from omi_quotes when the zone label matches.
drop view if exists stimaimmobile.zone_rates;
drop function if exists stimaimmobile.list_zone_coverage();

create or replace function stimaimmobile.lookup_zone_rate(p_comune text, p_zona text, p_destinazione text)
returns table (
  comune text,
  zona text,
  destinazione text,
  euro_mq numeric,
  euro_mq_min numeric,
  euro_mq_max numeric,
  fonte text,
  data_riferimento date,
  source text
)
language plpgsql
stable
security definer
set search_path = pg_catalog, stimaimmobile
as $$
begin
  return query
  select r.comune, r.zona, r.destinazione, r.euro_mq,
         coalesce(band.compr_min, r.euro_mq),
         coalesce(band.compr_max, r.euro_mq),
         r.fonte, r.data_riferimento,
         case when r.fonte = 'Agenzia delle Entrate – OMI' then 'omi'::text else 'listino'::text end
  from stimaimmobile.rates r
  left join lateral (
    select qq.compr_min, qq.compr_max
    from stimaimmobile.omi_quotes qq
    left join stimaimmobile.omi_zones zz
      on zz.semester = qq.semester and zz.link_zona = qq.link_zona
    where lower(trim(qq.comune)) = lower(trim(r.comune))
      and lower(trim(left(coalesce(nullif(trim(zz.zona_descr), ''), qq.zona), 150))) = lower(trim(r.zona))
      and lower(trim(left(qq.tipologia, 150))) = lower(trim(r.destinazione))
      and qq.semester = (select max(semester) from stimaimmobile.omi_quotes)
      and (coalesce(qq.compr_min, 0) > 0 or coalesce(qq.compr_max, 0) > 0)
    order by
      case when qq.stato_prevalente then 0 when lower(trim(qq.stato)) = 'normale' then 1 else 2 end
    limit 1
  ) band on true
  where lower(trim(r.comune)) = lower(trim(p_comune))
    and lower(trim(r.zona)) = lower(trim(p_zona))
    and lower(trim(r.destinazione)) = lower(trim(p_destinazione))
  limit 1;
end;
$$;

revoke all on function stimaimmobile.lookup_zone_rate(text, text, text) from public, anon, authenticated;
grant execute on function stimaimmobile.lookup_zone_rate(text, text, text) to stimaimmobile_app;

